use std::process::Command;
use std::os::unix::ffi::OsStrExt;
use std::ffi::OsStr;

fn run(bytes: &[u8]) -> [u8;4] {
    let out = Command::new("/workspace/dataset/test4_executable")
        .arg(OsStr::from_bytes(bytes)).output().unwrap();
    let s = String::from_utf8_lossy(&out.stdout);
    let v: Vec<u8> = s.lines().map(|l| if l.trim()=="1" {1u8} else {0u8}).collect();
    let mut r=[9u8;4];
    for i in 0..4 { if i<v.len() { r[i]=v[i]; } }
    r
}
fn model(b: &[u8]) -> [u8;4] {
    let l = b.len();
    let hi = b.iter().any(|&c| c>=0x80);
    [ if l>=1 && l<=255 {1} else {0},
      if l>=1 && l<=63 {1} else {0},
      if hi {0} else {1},
      if hi {1} else {0} ]
}
// xorshift rng
struct R(u64);
impl R { fn n(&mut self)->u64{ let mut x=self.0; x^=x<<13; x^=x>>7; x^=x<<17; self.0=x; x } }

fn main(){
    let mut rng = R(0x12345678deadbeef);
    let mut mismatches = 0usize;
    let mut checked = 0usize;
    // alphabet pools
    let pools: Vec<Vec<u8>> = vec![
        (1u8..=127u8).collect(),                 // all ascii non-nul
        (0x80u8..=0xFFu8).collect(),             // all high bytes (invalid utf8 mostly)
        b"aZ9-_.".to_vec(),
        "\u{4F8B}\u{FC}\u{1F600}\u{DF}\u{30A2}\u{20AC}\u{FB01}~!".as_bytes().to_vec(),
        (1u8..=255u8).collect(),                 // everything
    ];
    // 1) exact-length sweep over many alphabets, L = 0..=400
    for pi in 0..pools.len() {
        for l in 0..=400usize {
            let mut b = Vec::with_capacity(l);
            while b.len() < l {
                let p = &pools[pi];
                b.push(p[(rng.n() as usize) % p.len()]);
            }
            b.truncate(l);
            if b.contains(&0) { continue; }
            let a = run(&b); let m = model(&b);
            checked+=1;
            if a!=m { mismatches+=1; if mismatches<=10 { println!("MISMATCH pool={} len={} act={:?} model={:?} bytes={:02x?}", pi, l, a, m, &b[..b.len().min(40)]); } }
        }
    }
    // 2) random lengths 0..600
    for _ in 0..3000 {
        let l = (rng.n() as usize) % 601;
        let pi = (rng.n() as usize) % pools.len();
        let mut b = Vec::with_capacity(l);
        while b.len() < l { let p=&pools[pi]; b.push(p[(rng.n() as usize)%p.len()]); }
        if b.contains(&0) { continue; }
        let a = run(&b); let m = model(&b);
        checked+=1;
        if a!=m { mismatches+=1; if mismatches<=20 { println!("MISMATCH2 len={} act={:?} model={:?} bytes={:02x?}", l, a, m, &b[..b.len().min(40)]); } }
    }
    println!("checked={} mismatches={}", checked, mismatches);
}
