use std::process::Command; use std::os::unix::ffi::OsStrExt; use std::ffi::OsStr;
fn run(b:&[u8])->String{ let o=Command::new("/workspace/dataset/test4_executable").arg(OsStr::from_bytes(b)).output().unwrap();
 String::from_utf8_lossy(&o.stdout).lines().collect::<Vec<_>>().join(" ") }
fn model(b:&[u8])->String{ let l=b.len(); let hi=b.iter().any(|&c|c>=0x80);
 format!("{} {} {} {}", if l>=1&&l<=255{1}else{0}, if l>=1&&l<=63{1}else{0}, if hi{0}else{1}, if hi{1}else{0}) }
fn main(){
 let specials: Vec<(&str,&str)> = vec![
  ("BOM U+FEFF","\u{FEFF}"),("ZWSP U+200B","\u{200B}"),("ZWJ U+200D","\u{200D}"),
  ("ZWNJ U+200C","\u{200C}"),("NBSP U+00A0","\u{00A0}"),("SOFTHYPH U+00AD","\u{00AD}"),
  ("U+007F","\u{7F}"),("U+0080","\u{80}"),("U+07FF","\u{7FF}"),("U+0800","\u{800}"),
  ("U+FFFF","\u{FFFF}"),("U+10000","\u{10000}"),("U+10FFFF","\u{10FFFF}"),
  ("combining U+0301","\u{301}"),("fullwidth dot U+FF0E","\u{FF0E}"),
  ("ideographic dot U+3002","\u{3002}"),("Kelvin U+212A","\u{212A}"),
 ];
 let mut bad=0;
 for (n,s) in &specials {
   for pad in [0usize,63,64,255,256] {
     let mut b = vec![b'a'; pad]; b.extend_from_slice(s.as_bytes());
     let a=run(&b); let m=model(&b);
     if a!=m { bad+=1; println!("MISMATCH {} pad={} L={} act='{}' model='{}'", n, pad, b.len(), a, m); }
