     let a2=run(&b2); let m2=model(&b2);
     if a2!=m2 { bad+=1; println!("MISMATCH-pre {} pad={} L={} act='{}' model='{}'", n, pad, b2.len(), a2, m2); }
   }
 }
 // dot-heavy near boundaries
 for l in 0..=300usize {
   for pat in [b".".to_vec(), b"a.".to_vec(), b"..".to_vec(), b".a.b".to_vec()] {
     let mut b=Vec::new(); while b.len()<l { b.extend_from_slice(&pat); } b.truncate(l);
     let a=run(&b); let m=model(&b);
     if a!=m { bad+=1; println!("MISMATCH-dot l={} act='{}' model='{}'", l,a,m); }
   }
 }
 println!("specials+dots done, mismatches={}", bad);
 println!("sample: BOM alone -> {}", run("\u{FEFF}".as_bytes()));
 println!("sample: 63a+BOM (L=66) -> {}", run(&{let mut v=vec![b'a';63]; v.extend("\u{FEFF}".as_bytes()); v}));
}
